    result_object = myBinPack.pack(bins = myBinPack.stock, parts = parts)

    assert result_object["placed"] == 8

    # assert result_object["packed_parts"]

    totalParts = 0
    for part_packed in result_object["parts_packed"]:
        root_packed_parts = ET.fromstring(part_packed)
        garment_paths = [
            elem for elem in root_packed_parts.iter()
            if elem.tag.endswith("path")
               and elem.attrib.get("role") == "garment"
        ]
        number_of_parts = len(garment_paths)
        print(f"Found {number_of_parts} garment pieces packed.")
        assert number_of_parts >= 0
        totalParts += number_of_parts

    print(f"Found {totalParts} parts packed.")

    root_garment_marker = ET.fromstring(result_object["garment_marker"])
    garment_marker_paths = [
        elem for elem in root_garment_marker.iter()
        if elem.tag.endswith("path")
           and elem.attrib.get("role") == "garment"
    ]
    number_of_parts = len(garment_marker_paths)
    print(f"Found {number_of_parts} parts in the garment marker of the expected {totalParts} parts.")
    assert number_of_parts == totalParts

    print(result_object["garment_marker"])